package com.drogaria.backend.controller;
import com.drogaria.backend.dto.*; import com.drogaria.backend.service.EstoqueService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/estoque") public class EstoqueController { private final EstoqueService s; public EstoqueController(EstoqueService s){this.s=s;} @GetMapping public List<EstoqueResponse> listar(){return s.listar();} @GetMapping("/{id}") public EstoqueResponse buscar(@PathVariable Integer id){return s.buscar(id);} @PostMapping public ResponseEntity<EstoqueResponse> salvar(@Valid @RequestBody EstoqueRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.salvar(r));} @PutMapping("/{id}") public EstoqueResponse atualizar(@PathVariable Integer id,@Valid @RequestBody EstoqueRequest r){return s.salvar(r);} @DeleteMapping("/{id}") public ResponseEntity<Void> excluir(@PathVariable Integer id){s.excluir(id);return ResponseEntity.noContent().build();} }